make-a-square-with-the-same-color:
class Solution:
    def canMakeSquare(self, grid: List[List[str]]) -> bool:
        for i in range(2):
            for j in range(2):
                w = b = 0
                for di in range(2):
                    for dj in range(2):
                        if grid[i+di][j+dj] == 'W': w +=  1
                        else: b +=  1
                if w == 1 or b ==  1:
                    return True
        return False

