minimum-number-of-pushes-to-type-word-i:
class Solution:
    def minimumPushes(self, word: str) -> int:
        from collections import Counter
        c = sorted(Counter(word).values(), reverse=True)
        ans =  0
        for i, v in enumerate(c):
            ans += (i//8 + 1)*v
        return ans

